INSERT INTO category (category_id, name, slug, url, created_at, created_by, modified_at, modified_by) VALUES (8, 'Guar & Guar Gum', 'guar-guar-gum', 'images/guar.png', CURRENT_TIMESTAMP, 'SYSTEM_USER', CURRENT_TIMESTAMP, 'SYSTEM_USER');
INSERT INTO product (product_id, category_id, name, slug, description, botanical_name, family_name, commercial_part, origin_and_distribution, uses, image_url, specifications, created_at, created_by, modified_at, modified_by) VALUES (1, 1, 'CUMIN SEEDS', 'cumin-seeds', 'Cumin seeds are the seeds of cuminum cyminum, which belongs to the parsley family. It is pale green in color and elliptical in shape with deep furrows. Cumin seeds has a penetrating flavour and aroma. Description Cumin is the dried, white fruit with greyish brown colour of a small slender annual herb. The surface of the fruit has 5 primary ridges, alternatively has 4 less distinct secondary ridges bearing numerous short hairs. The plant is 15 to 50 cm high. The aromatic seed like fruit is elongated, ovoid, 3 to 6 mm long, slightly bitter and has a warm flavour. The flowers are white or rose coloured in small umbels. Apiaceae Fruit', '', '', 'Cuminum cyminum L.', 'Cumin is indigenous to Northern Egypt, Syria, the Mediterranean region, Iran and India. It is also cultivated in Mexico, China, Sicily and Malta. Cumin is a tropical plant and is cultivated as a rabi crop in areas where atmospheric humidity during February-March is low.', 'Cumin seed have an aromatic odour and bitter taste. It is used as a condiment, and is an ingredient in curry powders, seasonings of breads, cakes and cheese. It is employed in native dishes of Central and South America. In medicine, it is used as a stimulant, carminative, stomachic and astringent. Cumin seed oil is used in perfumery and for flavouring liqueurs and cordials.', 'images/cumin-seeds.jpg', '{"Purity": "99% Min", "Admixture": "1% Max", "Moisture": "9% Max"}', CURRENT_TIMESTAMP, 'SYSTEM_USER', CURRENT_TIMESTAMP, 'SYSTEM_USER');
INSERT INTO product (product_id, category_id, name, slug, description, botanical_name, family_name, commercial_part, origin_and_distribution, uses, image_url, specifications, created_at, created_by, modified_at, modified_by) VALUES (2, 1, 'FENNEL SEEDS', 'fennel-seeds', 'Fennel Seeds (Sauf) are very effective for digestive problems. These seeds can be chewed upon or had as a tea decoction for beneficial effects upon the stomach. In India, these are routinely chewed upon after meals to aid in digestion after a rich meal while acting as a herbal mouth freshener. Fennel seeds often provide quick and effective relief from many digestive disorders. They help to overcome gas, cramps, acid indigestion, and many other digestive tract maladies. Fennel is a perennial, pleasant-smelling herb with yellow flowers. It is native to the Mediterranean, but is now found throughout the world. Dried fennel seeds are often used in cooking as an anise-flavored spice. But don’t confuse fennel with anise; though they look and taste similar, they are not the same. Fennel’s dried ripe seeds and oil are used to make medicine. Fennel is used for various digestive problems including heartburn, intestinal gas,bloating, loss of appetite, and colic in infants.It is also used for upper respiratory tract infections,coughs, bronchitis, cholera, backache, bedwetting, and visual problems. Some women use fennel for increasing the flow of breast milk, promoting menstruation, easing the birthing process, and increasing sex drive. Fennel powder is used as a poultice for snakebites. In foods and beverages, fennel oil is used as a flavoring agent. In other manufacturing processes, fennel oil is used as a flavoring agent in certain laxatives, and as a fragrance component in soaps and cosmetics.', '', '', '', '', '', 'images/fennel-seeds.jpg', '{"Purity": "99% Min", "Moisture": "10% Max", "Admixture": "1% Max"}', CURRENT_TIMESTAMP, 'SYSTEM_USER', CURRENT_TIMESTAMP, 'SYSTEM_USER');
INSERT INTO product (product_id, category_id, name, slug, description, botanical_name, family_name, commercial_part, origin_and_distribution, uses, image_url, specifications, created_at, created_by, modified_at, modified_by) VALUES (3, 1, 'RED CHILLIES', 'red-chillies', 'We are one of the leading supplier of fine quality red chilly, which is famous for its aroma and rich red colour. The red chilly brought in our firm is kept in appropriate conditions within our warehouse so as to maintain its freshness, crispiness and its distinct smell. Chosen from the best of farms located in selected regions. We are offering different kind of chilly grounded / powder, chilly flakes (Kibbled-Pizza Cut) in assorted heat value (Schouville) & color index (Asta). We offer all Indian varieties of red chillies like 334, S-4, S7(Bird Eye & Semibird Eye), S9 (Round-Mundu). Also known as red pepper with different schouville values & Asta colour. Red chillies are used in different cuisines to make the food more delicious and tasty. Chilli is the dried ripe fruit of the genus Capsicum. Capsicum annum is an annual sub –shrub, the flowers of which are borne singly and fruits usually pendent, which provide red peppers, cayenne, paprika and chillies and sweet pepper (bell pepper) a mild form with large inflated fruits. Capsicum frutescence is a perennial chilly with small sized pods which are highly pungent. It is commonly known as ‘bird chilly’ and ‘Tabasco’. Capsicum frutescens L. Solanaceae Green as well as ripe and dried pod (fruit)', '', '', 'Capsicum annum L.,', '', '', 'images/red-chillies.jpg', '{"Type": "S-4 / 334 / Mundu", "Moisture": "12% Max", "Admixture": "1% Max"}', CURRENT_TIMESTAMP, 'SYSTEM_USER', CURRENT_TIMESTAMP, 'SYSTEM_USER');
INSERT INTO product (product_id, category_id, name, slug, description, botanical_name, family_name, commercial_part, origin_and_distribution, uses, image_url, specifications, created_at, created_by, modified_at, modified_by) VALUES (4, 1, 'CORIANDER SEEDS', 'coriander-seeds', 'Among one of the first spices used by mankind, coriander seeds, is the seed of coriandrum sativum, which belongs to the parsley family. The coriander seeds are almost oval in shape and greenish to yellowish in color. It is a fragrant spice, with a mild, distinctive taste. It is widely used as a condiment in foods, beverages, marinades, desserts and sweet pastries and American cigarettes. It is also valued for its medicinal properties. This fragrant spice is known for its medicinal properties and used as a condiments in curries; as fresh leaves for garnishing of curries, and in chutney as an appetiser. Apiaceae Leaf and seed', '', '', 'Coriandrum sativam L.', 'It is a native of Mediterranean and commercially produced in India, Morocco, Russia, East European countries, France, Central America, Mexico, and USA. Coriander is a tropical crop and can be successfully cultivated as a rabi season crop in an area free from severe frost during February when the crop flowers and sets its seeds', '', 'images/coriander-seeds.jpg', '{"Purity": "99% Min", "Split seeds": "5% Max", "Moisture": "9% Max"}', CURRENT_TIMESTAMP, 'SYSTEM_USER', CURRENT_TIMESTAMP, 'SYSTEM_USER');
INSERT INTO product (product_id, category_id, name, slug, description, botanical_name, family_name, commercial_part, origin_and_distribution, uses, image_url, specifications, created_at, created_by, modified_at, modified_by) VALUES (5, 1, 'FENUGREEK SEEDS', 'fenugreek-seeds', 'Fenugreek seed whole consist of dried ripe seed of trigonella foenumgraecum. The colour is carramel to light brownish-yellow. Odour and taste are typical, a bit of cellery and bitter. Free from foregn odour and taste, such as mustiness or rancidity . Fenugreek has a strong, pleasant and quite peculiar odour. Fenugreek seed is the ripe fruit of an annual herb. This robust herb has light green leaves, is 30-60 cm tall and produces slender, beaked pods, 10-15 cm long, each pod contains 10-20 small hard yellowish brown seeds, which are smooth and oblong, about 3mm long. Fabaceae Fruit', '', '', 'Trigonella foenum-graecum L.', 'Fenugreek is a native of South Eastern Europe and West Asia, now cultivated in India, Argentina, Egypt and Mediterranean countries (Southern France, Morocco and Lebanon). In India it is grown extensively in Rajasthan, Gujarat, Madhya Pradesh, Uttar Pradesh, Maharashtra and Punjab.It is a cold season crop and is fairly tolerant to frost and very low temperature. It is best suited to tracts of moderate to low rainfall and is sown in all types of soil but perform better in loam and clayey loam with proper drainage. It can also be grown on black cotton soils.', '', 'images/fenugreek-seeds.jpg', '{"Purity": "99% Min", "Moisture": "10% Max", "Admixture": "1% Max"}', CURRENT_TIMESTAMP, 'SYSTEM_USER', CURRENT_TIMESTAMP, 'SYSTEM_USER');
INSERT INTO product (product_id, category_id, name, slug, description, botanical_name, family_name, commercial_part, origin_and_distribution, uses, image_url, specifications, created_at, created_by, modified_at, modified_by) VALUES (6, 1, 'DILL SEEDS', 'dill-seeds', 'Dill is the dried fruit of the herb anethum graveolens, which belongs to the parsley family. Dill seeds are oval-shaped, soft and fluffy and has a pungent and aromatic flavor. Dill seeds have been used since ancient times. Description Dill is a herbaceous annual with pinnately divided leaves. The ripe, light brown seeds emit an aromatic odour. The leaves have pleasant aromatic odour and warm taste. Both seeds and leaves are valued as spice. Apiaceae Fruit', '', '', 'Anethum graveoluns L.', 'European Dill (Anetheum graveolens) is indigenous to Europe and is cultivated in England, Germany, Romania, Turkey, USA and Russia. The Indian dill (Anetheum sowa), a native of Northern India is bolder than the European dill. It is cultivated as a cold weather crop in many parts of India.', '', 'images/dill-seeds.jpg', '{}', CURRENT_TIMESTAMP, 'SYSTEM_USER', CURRENT_TIMESTAMP, 'SYSTEM_USER');
INSERT INTO product (product_id, category_id, name, slug, description, botanical_name, family_name, commercial_part, origin_and_distribution, uses, image_url, specifications, created_at, created_by, modified_at, modified_by) VALUES (7, 1, 'BLACK PEPPER', 'black-pepper', 'We are exporting high quality Black pepper in bulk quality as per client requirements. The Black pepper that we export is hygienically packaged and is free from impurities. Our customers can avail Black pepper from us in packs of different quantities as per their requirements. Black Pepper is the dried mature berries of Piper Nigrum grown in South India, garbled, dark brown to dark black in colour nearly globular, with a wrinkled surface. Light berry contents to be tested by floatation method in alcohol or methylated spirit of 0.80 to 0.82 specific gravity at room temperature (around 25°C). Piperaceae', '', 'Piper nigrum Linn', '', '', '', 'images/black-pepper.jpg', '{"Moisture": "12% Max", "Purity": "99% Min", "Pinheads": "1% Max"}', CURRENT_TIMESTAMP, 'SYSTEM_USER', CURRENT_TIMESTAMP, 'SYSTEM_USER');
INSERT INTO product (product_id, category_id, name, slug, description, botanical_name, family_name, commercial_part, origin_and_distribution, uses, image_url, specifications, created_at, created_by, modified_at, modified_by) VALUES (8, 1, 'TURMERIC', 'turmeric', 'The whole turmeric is a tuberous rhizome, with a rough, segmented skin. The rhizome is yellowish-brown with a dull orange interior that looks bright yellow when powdered. Our high quality turmeric acts as a mild digestive, being aromatic, a stimulant and a carminative. An ointment base on the spice is used as an antiseptic, its water is used as a cosmetic applied to impart a golden glow to the complexion. We are specialized in turmeric of assorted varieties of curcumin value. Turmeric, The primary rhizomes, round in shape are called ''bulbs'', while the thin, long secondary rhizomes are ''fingers''. It has a characterized fragrance, peppery aroma & it’s slightly bitter in taste with a musky flavor. Zingiberaceae Rhizome or underground stem', '', '', 'Curcuma longa L.', 'Turmeric is a tropical crop cultivated from sea level to 1200 meter MSL. It grows in light black, black clayey loams and red soils in irrigated and rainfed conditions. The crop cannot stand water logging or alkalinity', '', 'images/turmeric.jpg', '{"Type": "Finger / Bulb", "Curcumin value": "2% - 5%"}', CURRENT_TIMESTAMP, 'SYSTEM_USER', CURRENT_TIMESTAMP, 'SYSTEM_USER');
INSERT INTO product (product_id, category_id, name, slug, description, botanical_name, family_name, commercial_part, origin_and_distribution, uses, image_url, specifications, created_at, created_by, modified_at, modified_by) VALUES (9, 2, 'BLACK MUSTARD SEEDS', 'black-mustard-seeds', 'Black mustard is a plant. The seed and oil from the seed are used to make medicine. Black mustard oil is used for the common cold, painful joints and muscles (rheumatism), and arthritis. Black mustard seed is used for causing vomiting, relieving water retention (edema) by increasing urine production, and increasing appetite. Some people make a paste by mixing ground black mustard seed with warm water. They pack the paste in cloth and apply the cloth directly to the skin as a “mustard plaster.” This preparation is used for treating pneumonia, pain and swelling (inflammation) of the lining of the lungs (pleurisy), arthritis, lower back pain (lumbago), and aching feet.In foods, black mustard leaves (greens) are used in salads and other dishes.', '', '', '', 'Mustard seeds can be white, yellow, black or brown, and are derived from three different plants. The black seeds are exceedingly pungent; they’re also difficult to harvest, volatile and thus more expensive. White seeds tend to be much milder but can have the fieriness of the black, depending on how they’re prepared. Black or brown mustard seeds are widely used in Indian, especially Bengali and Southern Asian, cooking. When fried, the taste is nutty rather than fiery.', '', 'images/black-mustard-seeds.jpg', '{"Purity": "99% Min", "Moisture": "9% Max"}', CURRENT_TIMESTAMP, 'SYSTEM_USER', CURRENT_TIMESTAMP, 'SYSTEM_USER');
INSERT INTO product (product_id, category_id, name, slug, description, botanical_name, family_name, commercial_part, origin_and_distribution, uses, image_url, specifications, created_at, created_by, modified_at, modified_by) VALUES (10, 2, 'GROUND NUTS', 'ground-nuts', 'We specialize in export of ground nut bold quality with assorted counts / size & also Java quality of assorted counts / size as per buyer requirements. We also supply with certification of aflatoxin guarantee. Ground nut is commonly called ''peanut'' has numerous areas of application of utility. It is used in forming anti aging drugs, used to make peanut butter and the shelled peanuts can be roasted and fried and consumed as a snack. Peanut is a major source of oil, which is mono saturated fat and is healthful type, which is prescribed for skin health. The ground nut oil that we provide are carefully grown and saved during the storage season when the ground nuts are prone to fungal infections. We supply the choicest of ground nuts, which have abundant oil.', '', '', '', '', '', 'images/ground-nuts.jpg', '{"Type": "Bold / Java", "Counts": "40/50, 50/60, 60/70"}', CURRENT_TIMESTAMP, 'SYSTEM_USER', CURRENT_TIMESTAMP, 'SYSTEM_USER');
INSERT INTO product (product_id, category_id, name, slug, description, botanical_name, family_name, commercial_part, origin_and_distribution, uses, image_url, specifications, created_at, created_by, modified_at, modified_by) VALUES (11, 2, 'SESAME SEEDS', 'sesame-seeds', 'We export different grades of Hulled sesame seed in terms of purity 99.98%, 99.95% & premium quality exports with certification of free from microbiological organism. Mechanically hulled and mechanically dried sesame seed consists of the hulled seed from the plant sesame indicum L. The colour is white. Odour and taste are typical, and free from foreign odour and taste, such as mustiness or rancidity. Purity 99.95% Min & 99.98% Premium Quality Salmonella Absent in 25 grams Yeast & Moulds < 1 0,000 CFU/ gram TPC < 1 ,00,000 CFU/ gram F. F. A. (as oleic acid) <2%', '', '', '', '', '', 'images/sesame-seeds.jpg', '{"Purity": "99.98% Min", "Salmonella": "Absent", "FFA": "< 2%"}', CURRENT_TIMESTAMP, 'SYSTEM_USER', CURRENT_TIMESTAMP, 'SYSTEM_USER');
INSERT INTO product (product_id, category_id, name, slug, description, botanical_name, family_name, commercial_part, origin_and_distribution, uses, image_url, specifications, created_at, created_by, modified_at, modified_by) VALUES (12, 2, 'BLACK SESAME SEEDS', 'black-sesame-seeds', 'Black sesame seeds (Sesamum Indicum L) are similar to the more common white sesame seeds. Black sesame seeds are not hulled, brown (golden) sesame seeds retain their hulls too, and the white seeds are hulled which exposes their true seed color. Lighter colored sesame seeds are used more in the West and in the Middle East, and the black sesame seeds are more popular in Far East cuisine. White and black sesame seeds can be used together for an attractive accent to any meal. Sesame seeds are rich in vitamins and minerals and offer several health related benefits. Black sesame seeds contain about 60% more calcium than hulled sesame seeds. Black Sesame Seeds are similar to the more common white sesame seeds. Black Sesame Seeds are not hulled. Black sesame seeds are more flavorful than hulled seeds. Sesame seeds are 40 to 60 percent oil. Sesame seeds are high in protein. Black Sesame Seeds add an attractive accent to food.', '', '', '', '', '', 'images/black-sesame-seeds.jpg', '{"Latin name": "Sesamum Indicum L"}', CURRENT_TIMESTAMP, 'SYSTEM_USER', CURRENT_TIMESTAMP, 'SYSTEM_USER');
INSERT INTO product (product_id, category_id, name, slug, description, botanical_name, family_name, commercial_part, origin_and_distribution, uses, image_url, specifications, created_at, created_by, modified_at, modified_by) VALUES (13, 2, 'CASTOR SEEDS', 'castor-seeds', 'The castor is a small annual plant. It ranges from 1 to 7 meters in height. It has well-developed roots, with green and reddish stems which become hollow with age. The fruit is a spherical capsule with small grey seeds with brown spots. The oil was, and is still, used extensively in local medicines mainly as a laxative, but also to soften dry and coarse skin. Castor Oil is tasteless and odorless oil that is extracted from Castor seeds obtained from the castor plant, which is scientifically known as Ricinus Communis. Castor Oil contains a toxin called Ricin (a protein) which, if administered in very low dosages, acts as a germicidal substance. Due to this property, it is also used as a spermicide in spermicidal gels, and lotions. Castor is used very effectively in the treatment of rheumatic and skin disorders. It is a harmless purgative', '', '', '', '', '', 'images/castor-seeds.jpg', '{}', CURRENT_TIMESTAMP, 'SYSTEM_USER', CURRENT_TIMESTAMP, 'SYSTEM_USER');
INSERT INTO product (product_id, category_id, name, slug, description, botanical_name, family_name, commercial_part, origin_and_distribution, uses, image_url, specifications, created_at, created_by, modified_at, modified_by) VALUES (14, 2, 'YELLOW MUSTARD SEEDS', 'yellow-mustard-seeds', 'Mustard seeds are the small seeds of the various mustard plants. The seeds are about 3 mm in diameter, and may be colored from yellowish to blaclish yellow. While there are approximately forty different varieties of mustard plants, there are three principal types used to make mustard seeds: black mustard (Brassica nigra), white mustard (Brassica alba) and brown mustard (Brassica juncea). Yellow mustard seeds have the most pungent taste, while white mustard seeds, which are actually yellow in color, are the most mild and are the ones used to make American yellow mustard.', '', '', '', '', 'Yellow Mustard powder and yellow mustard seeds should be kept in a tightly sealed container in a cool, dark and dry place. Prepared yellow mustard and mustard oil should both be refrigerated.', 'images/yellow-mustard-seeds.jpg', '{"Purity": "99% Min", "Moisture": "9% Max"}', CURRENT_TIMESTAMP, 'SYSTEM_USER', CURRENT_TIMESTAMP, 'SYSTEM_USER');
INSERT INTO product (product_id, category_id, name, slug, description, botanical_name, family_name, commercial_part, origin_and_distribution, uses, image_url, specifications, created_at, created_by, modified_at, modified_by) VALUES (15, 2, 'WATERMELON SEEDS', 'watermelon-seeds', 'Watermelon is an extremely popular fruit. While we all enjoy eating this sweet refreshing fruit, we usually discard the tiny seeds scattered in it without realizing or rather knowing of their health benefits. These seeds are loaded with nutrients including fatty acids, essential proteins and lots of minerals. These seeds are rich in vitamin B like thiamine, niacin, folate and minerals like magnesium, potassium, manganese, iron, zinc, phosphorus and copper. Besides, they are a great source of calories with 100 grams of watermelon seeds providing around 600 grams of calories.', '', '', '', 'The watermelon is an annual plant with long, weak, trailing or climbing stems which are five-angled and up to 3 m (10 ft) long. Young growth is densely woolly with yellowish-brown hairs which disappear as the plant ages. The leaves are stemmed and are alternate, large and pinnately-lobed, stiff and rough when old. The plant has branching tendrils. The flowers grow singly in the leaf axils and the corolla is white or yellow inside and greenish-yellow on the underside. The flowers are unisexual, with male and female flowers occurring on the same plant (monoecious).', '', 'images/watermelon-seeds.jpg', '{}', CURRENT_TIMESTAMP, 'SYSTEM_USER', CURRENT_TIMESTAMP, 'SYSTEM_USER');
INSERT INTO product (product_id, category_id, name, slug, description, botanical_name, family_name, commercial_part, origin_and_distribution, uses, image_url, specifications, created_at, created_by, modified_at, modified_by) VALUES (16, 3, 'RED CHILLI POWDER', 'red-chilli-powder', 'Chili powder is a widely used spice in various soups, stews, and -- of course -- chilis. It can also be used as a component of marinades or dry rubs for meats as well as incorporated into burgers. Chili powder is actually a fairly healthy seasoning, with significant amounts of several beneficial nutrients. We offer all Indian varieties of red chillies like 334, S-4, S7(Bird Eye & Semibird Eye), S9 (Round-Mundu). Also known as red pepper with different schouville values & Asta colour. Red chillies are used in different cuisines to make the food more delicious and tasty. Chili powder is also rich in several important minerals. One tablespoon contains 143.7 milligram of potassium, or 4.1 percent of your daily recommendation; 22.7 milligram of phosphorus, or 2.3 percent of your daily recommendation; 20.9 milligrams of calcium, or 2.1 percent of your daily recommendation; and 1.1 milligrams of iron, or 5.9 percent of your daily recommendation. It also contains 0.2 mg each of zinc and manganese and 0.5 micorgrams of selenium. Capsicum frutescence is a perennial chilly with small sized pods which are highly pungent. It is commonly known as ‘bird chilly’ and ‘Tabasco’. Capsicum frutescens L. Solanaceae Green as well as ripe and dried pod (fruit)', '', '', 'Capsicum annum L.,', '', '', 'images/red-chilli-powder.jpg', '{"Type": "S-4 / 334 / Mundu", "Moisture": "12% Max", "Admixture": "1% Max"}', CURRENT_TIMESTAMP, 'SYSTEM_USER', CURRENT_TIMESTAMP, 'SYSTEM_USER');
INSERT INTO product (product_id, category_id, name, slug, description, botanical_name, family_name, commercial_part, origin_and_distribution, uses, image_url, specifications, created_at, created_by, modified_at, modified_by) VALUES (17, 3, 'CUMIN POWDER', 'cumin-powder', 'Cumin is available both in its whole seed form and ground into a powder. Description Although the small cumin seed looks rather unassuming, it packs a punch when it comes to flavor, which can be described as penetrating and peppery with slight citrus overtones. Cumin''s unique flavor complexity has made it an integral spice in the cuisines of Mexico, India and the Middle East. Apiaceae Fruit', '', '', 'Cuminum cyminum L.', 'Cumin is indigenous to Northern Egypt, Syria, the Mediterranean region, Iran and India. It is also cultivated in Mexico, China, Sicily and Malta. Cumin is a tropical plant and is cultivated as a rabi crop in areas where atmospheric humidity during February-March is low.', '.', 'images/cumin-powder.jpg', '{"Purity": "99% Min", "Admixture": "1% Max", "Moisture": "9% Max"}', CURRENT_TIMESTAMP, 'SYSTEM_USER', CURRENT_TIMESTAMP, 'SYSTEM_USER');
INSERT INTO product (product_id, category_id, name, slug, description, botanical_name, family_name, commercial_part, origin_and_distribution, uses, image_url, specifications, created_at, created_by, modified_at, modified_by) VALUES (18, 3, 'CORIANDER POWDER', 'coriander-powder', 'According to Bright Fame powdered coriander is good for digestion. It also increases appetite. It helps in purifying the blood and curing inflammation, fever and as well as various allergies. Due to ''cooling'' qualities of coriander, this spice is considered to be very beneficial for restoring the ''Pitta'' balance. Due to ''strong'' qualities of this wonderful spice, it is always advisable to consume it on the advise of a qualified practitioner of Ayurvedic medicine. If consumed in smaller quantities it can be beneficial for Vata and Kapha also. Coriander also helps in cleansing the body by detoxifying it. Coriander has a strong aroma. In powdered form, it can be consumed either independently or after mixing it with certain other Ayurvedic spices. In powdered form, Coriander is generally taken with water. Apiaceae Leaf and seed', '', '', 'Coriandrum sativam L.', '', 'Pure coriander powder has a stringent taste and it may not be easy to consume it in its pure form. Apart from water, it is also taken with milk.', 'images/coriander-powder.jpg', '{"Purity": "99% Min", "Split seeds": "5% Max", "Moisture": "9% Max"}', CURRENT_TIMESTAMP, 'SYSTEM_USER', CURRENT_TIMESTAMP, 'SYSTEM_USER');
INSERT INTO product (product_id, category_id, name, slug, description, botanical_name, family_name, commercial_part, origin_and_distribution, uses, image_url, specifications, created_at, created_by, modified_at, modified_by) VALUES (19, 3, 'FENUGREEK POWDER', 'fenugreek-powder', 'Fenugreek or methi is a popular spice having a strong scent and a pungent flavor. Though it is mostly used for culinary purposes, it has a number of medicinal and beauty benefits too.Fenugreek powder is the dust form of the spice and is easily available in the market. You can also prepare it in your home by grinding dried fenugreek seeds thoroughly. Fabaceae Fruit', '', '', 'Trigonella foenum-graecum L.', 'It is a cold season crop and is fairly tolerant to frost and very low temperature.', 'Diabetic people can be very much benefited by fenugreek powder. The galactomannan present in the spice is capable of decelerating the absorption rate of sugar into our bloodstream. Additionally, it comprises almost all essential amino acids that can stimulate the production of insulin. Both of these are effective in controlling diabetes. Powdered fenugreek is also good for curing high fever and respiratory diseases. It can help us get relief from sore throat and chronic cough.', 'images/fenugreek-powder.jpg', '{"Purity": "99% Min", "Moisture": "10% Max", "Admixture": "1% Max"}', CURRENT_TIMESTAMP, 'SYSTEM_USER', CURRENT_TIMESTAMP, 'SYSTEM_USER');
INSERT INTO product (product_id, category_id, name, slug, description, botanical_name, family_name, commercial_part, origin_and_distribution, uses, image_url, specifications, created_at, created_by, modified_at, modified_by) VALUES (20, 3, 'TURMERIC POWDER', 'turmeric-powder', 'Turmeric powder is a bright yellow powder made by dry grinding of mature turmeric rhizomes (underground stems). The use of turmeric for coloring and flavoring food, for cosmetic purposes and for medicinal properties dates back to the ancient Vedic culture of India. Used in almost all Indian curries, this spice has almost no calories (1 tablespoon = 24 calories) and zero cholesterol. It is rich in dietary fiber, iron, potassium, magnesium and vitamin B6. Turmeric, The primary rhizomes, round in shape are called ''bulbs'', while the thin, long secondary rhizomes are ''fingers''. It has a characterized fragrance, peppery aroma & it’s slightly bitter in taste with a musky flavor. Zingiberaceae Rhizome or underground stem', '', '', 'Curcuma longa L.', 'It is a native of India. Apart from India, it is cultivated in Pakistan, Malaysia, Myanmar, Vietnam, Thailand, Philippines, Japan, Korea, China, Sri Lanka, Nepal, East & West Africa, South Pacific Islands, Malagasy, Caribbean Islands and Central America. In India, it is cultivated in the States of Andhra Pradesh, Maharashtra, Orissa, Tamil Nadu, Karnataka and Kerala.', 'to ward of insects, ants, and termites.', 'images/turmeric-powder.jpg', '{"Type": "Finger / Bulb", "Curcumin value": "2% - 5%"}', CURRENT_TIMESTAMP, 'SYSTEM_USER', CURRENT_TIMESTAMP, 'SYSTEM_USER');
INSERT INTO product (product_id, category_id, name, slug, description, botanical_name, family_name, commercial_part, origin_and_distribution, uses, image_url, specifications, created_at, created_by, modified_at, modified_by) VALUES (21, 4, 'ISABGOL (PSYLLIUM HUSK)', 'isabgol-psyllium-husk', 'We supply high quality Psyllium Husk that is used for water-soluble polymers, colon cleansing, trackifier and erosion control industry. Psyllium Husk is also finds application in various health-related applications like, heart disease, colon function, and weight control, diabetes-blood glucose control, diverticolosis and divertculitis. Hygienically packed, these Psyllium Husk are offered at industry leading prices. Our psyllium husk is also known as plantago ovata, isabgol, plantigini semen.', '', '', '', '', '', 'images/isabgol-psyllium-husk.jpg', '{}', CURRENT_TIMESTAMP, 'SYSTEM_USER', CURRENT_TIMESTAMP, 'SYSTEM_USER');
INSERT INTO product (product_id, category_id, name, slug, description, botanical_name, family_name, commercial_part, origin_and_distribution, uses, image_url, specifications, created_at, created_by, modified_at, modified_by) VALUES (22, 4, 'SENNA LEAVES', 'senna-leaves', 'Seena is an Arabian name, and the drug was first brought into use by the Arabian physicians Serapion and Mesue, and Achiarius was the first of the Greeks to notice it. He recommends not the leaves but the fruit, and Mesue also prefers the pods to the leaves, thinking them more powerful, though they are actually less so, but they do not cause griping. Senna is a powerful cathartic used in the treatment of constipation, working through a stimulation of intestinal peristalsis.', '', '', '', '', '', 'images/senna-leaves.jpg', '{}', CURRENT_TIMESTAMP, 'SYSTEM_USER', CURRENT_TIMESTAMP, 'SYSTEM_USER');
INSERT INTO product (product_id, category_id, name, slug, description, botanical_name, family_name, commercial_part, origin_and_distribution, uses, image_url, specifications, created_at, created_by, modified_at, modified_by) VALUES (23, 4, 'HALAM (ASALIA)', 'halam-asalia', 'We offer a high quality range of Halam (Asalia) which is great demand in the national and international market. These are procured from certified vendors and are hygienically packed in order to ensure their freshness and aroma. We offer our range in various size packaging, to suit the customer requirements.', '', '', '', '', '', 'images/halam-asalia.jpg', '{}', CURRENT_TIMESTAMP, 'SYSTEM_USER', CURRENT_TIMESTAMP, 'SYSTEM_USER');
INSERT INTO product (product_id, category_id, name, slug, description, botanical_name, family_name, commercial_part, origin_and_distribution, uses, image_url, specifications, created_at, created_by, modified_at, modified_by) VALUES (24, 4, 'AJWAIN (BISHOP WEED)', 'ajwain-bishop-weed', 'It is a common sight in India to see mothers and grandmothers handing out ajwain seeds to family members who have an upset stomach. Carom seeds or bishop’s weed also known as ajwain is a common herb found in Indian households and is well known for properties that make it one of the most used home remedies. But other than being a good digestive aid, it has a number of other health benefits.', '', '', '', '', '', 'images/ajwain-bishop-weed.jpg', '{}', CURRENT_TIMESTAMP, 'SYSTEM_USER', CURRENT_TIMESTAMP, 'SYSTEM_USER');
INSERT INTO product (product_id, category_id, name, slug, description, botanical_name, family_name, commercial_part, origin_and_distribution, uses, image_url, specifications, created_at, created_by, modified_at, modified_by) VALUES (25, 5, 'MASOOR DAL (SPLIT LENTIL)', 'masoor-dal-split-lentil', 'Masoor dal is an important part of the diet in many parts of the world, especially in the Indian subcontinent, which has a large vegetarian population. It is basically split lentil without skin and is red in colour. It does not need soaking prior to cooking as it is a soft dal and cooks quickly. When cooked, masoor dal turns a soft golden colour and has a pleasant earthy flavour. With 26 per cent protein, these lentils have the third-highest level of protein, by weight, of any plant-based food after soybeans and hemp. Health benefits are as follows: Masoor dal contains high levels of proteins, including the essential amino acids isoleucine and lysine, and is an essential source of inexpensive protein in many parts of the world for those who adhere to a vegetarian diet or cannot afford meat. Apart from a high level of proteins, masoor dal also contains dietary fibre, Folate, vitamin B1, and minerals, all with virtually no fat. Masoor dal is rich in fibre but lesser than the percentage present in whole and husked dals. They are a good source of potassium and iron.', '', '', '', '', '', 'images/masoor-dal-split-lentil.jpg', '{}', CURRENT_TIMESTAMP, 'SYSTEM_USER', CURRENT_TIMESTAMP, 'SYSTEM_USER');
INSERT INTO product (product_id, category_id, name, slug, description, botanical_name, family_name, commercial_part, origin_and_distribution, uses, image_url, specifications, created_at, created_by, modified_at, modified_by) VALUES (26, 6, 'MILLET', 'millet', 'The Millets provided by us are highly appreciated for their premium quality and are known for their longer shelf life. These are small-seeded spices, which are processed using hygienic grains. Further, these help in growing fodder and food and can be customized as per the needs of valued customers. In addition to this, these are renowned for forming highly functional group. Millet is always popular and demanded by consumers at a large scale whether it is white millet or green millet. Millet available with us ensures you the best quality and rich nutrition. Being a part of healthy diet green millet is also exported to various countries. We are glad to invite you for making a purchase of millet from our best quality storage.', '', '', '', '', '', 'images/millet.jpg', '{}', CURRENT_TIMESTAMP, 'SYSTEM_USER', CURRENT_TIMESTAMP, 'SYSTEM_USER');
INSERT INTO product (product_id, category_id, name, slug, description, botanical_name, family_name, commercial_part, origin_and_distribution, uses, image_url, specifications, created_at, created_by, modified_at, modified_by) VALUES (27, 6, 'MAIZE', 'maize', 'In our wide range of products, we also have Maize (White & Yellow) for our clients. Our product range is sub-categorized into yellow maize and white maize. The yellow maize has high nutritional content, can be used in cooking, and can also be eaten as raw. The genuine quality maize is easily available in the market at competitive prices.', '', '', '', '', '', 'images/maize.jpg', '{}', CURRENT_TIMESTAMP, 'SYSTEM_USER', CURRENT_TIMESTAMP, 'SYSTEM_USER');
INSERT INTO product (product_id, category_id, name, slug, description, botanical_name, family_name, commercial_part, origin_and_distribution, uses, image_url, specifications, created_at, created_by, modified_at, modified_by) VALUES (28, 6, 'BARLEY', 'barley', 'Barley is a wonderfully versatile cereal grain with a rich nutlike flavor and an appealing chewy, pasta-like consistency. Its appearance resembles wheat berries, although it is slightly lighter in color. Sprouted barley is naturally high in maltose, a sugar that serves as the basis for both malt syrup sweetener. In scientific studies, barley has been shown to reduce the risk of many diseases, and to provide important health benefits. Barley offers many of the same healthy vitamins and minerals as other whole grains, but many think its special health benefits stem from the high levels of soluble beta-glucan fiber found in this grain. Barley, like all whole grains, reduces blood pressure. Eating barley has been shown to lower LDL "bad" cholesterol and may help reduce the risk of heart disease. Barley may help you feel full longer, and thereby help you control your weight. Barley – even pearl barley – may help reduce visceral fat and waist circumference.', '', '', '', '', '', 'images/barley.jpg', '{}', CURRENT_TIMESTAMP, 'SYSTEM_USER', CURRENT_TIMESTAMP, 'SYSTEM_USER');
INSERT INTO product (product_id, category_id, name, slug, description, botanical_name, family_name, commercial_part, origin_and_distribution, uses, image_url, specifications, created_at, created_by, modified_at, modified_by) VALUES (29, 7, 'COTTON BALES', 'cotton-bales', 'Cotton Bales it is cotton packed in bales form. This cotton says as good variety, it is produced in only Gujarat (India). Cotton bales are a result of Ginning and Pressing Process of cotton. Our Ginning Unit separate cotton fibers and seeds from Cotton crop, Wes use only best quality raw materials to ensure a highly reliable production. We taking Care during the complete mechanical process of produce Cotton bales.', '', '', '', '', '', 'images/cotton-bales.jpg', '{"Staple length": "28 mm to 30 mm", "Strength": "27 to 30 gm / tex", "Microniare": "3.8 to 4.3", "Uniformity Ratio": "83%+", "Elongation": "5.5 to 6.5 %", "Maturity": "72+ %"}', CURRENT_TIMESTAMP, 'SYSTEM_USER', CURRENT_TIMESTAMP, 'SYSTEM_USER');
INSERT INTO product (product_id, category_id, name, slug, description, botanical_name, family_name, commercial_part, origin_and_distribution, uses, image_url, specifications, created_at, created_by, modified_at, modified_by) VALUES (30, 7, 'COTTON YARN', 'cotton-yarn', 'India produces a comprehensive range of yarns for every conveyable end use – non-spun or open-end; combed or carded, basic, compact, mélange or fancy. India’s 1943 spinning mills produce them all for requirements ranging from a fine 200 count to a coarse 2 count. The world’s most renowned Indian Cotton Yarns are available as greige, bleached, mercerized, gassed, twisted, dyed or an endless range of fashion yarns like mélange, stretch, blends, high twist and so on to meet the different applications in fashion, clothing, home textiles, hosiery and industrial fabrics. India can meet every customer requirement whether large or small, regular or customized, premium or basic. Constant induction of state-of-the-art technologies like compact spinning, using the most advanced yarn – processing technology and high-precision process controls tools like electronic cleaners, auto slavers, splicers, two-for-one twisters and auto-coners give Indian mills a competitive advantage. Today, Indian yarn is widely accepted in International markets as the exporters here regularly meet the needs of importers with unmatched efficiency and economy in countries like USA, Italy, Spain, Japan, China, South Korea, Taiwan, Bangladesh, Vietnam etc.', '', '', '', '', '', 'images/cotton-yarn.jpg', '{}', CURRENT_TIMESTAMP, 'SYSTEM_USER', CURRENT_TIMESTAMP, 'SYSTEM_USER');
INSERT INTO product (product_id, category_id, name, slug, description, botanical_name, family_name, commercial_part, origin_and_distribution, uses, image_url, specifications, created_at, created_by, modified_at, modified_by) VALUES (31, 8, 'GUAR SEEDS', 'guar-seeds', 'The processing machineries used by our company are packed with latest technologies to high quality products. The latest innovation and research has enabled the company to absorb contemporary technologies to swiftly change with the changing scenario of technology in the market. Gum is derived from guar seeds or cyamopsis tetragonoloba termed as Guar Gum. Guar Gum can also be termed as guaran. These seeds have high low-shear viscosity as evaluated with other hydrocolloids like (locust bean gum). Guar Gums are effective thickeners and stabilizers. Guar Gum is relatively cost effective as compared to other thickeners and stabilizers along with it being an effective binder, plasticizer and emulsifier. One of the important properties of guar gum, a polysaccharide, is that it is high on galactose and mannose. Guar gum is also known as guarkernmehl, guaran, goma guar, gomme guar and galactomannan.', '', '', '', '', '', 'images/guar-seeds.jpg', '{}', CURRENT_TIMESTAMP, 'SYSTEM_USER', CURRENT_TIMESTAMP, 'SYSTEM_USER');
INSERT INTO product (product_id, category_id, name, slug, description, botanical_name, family_name, commercial_part, origin_and_distribution, uses, image_url, specifications, created_at, created_by, modified_at, modified_by) VALUES (32, 8, 'GUAR GUM POWDER', 'guar-gum-powder', 'We are into the manufacturing of the Tailor made products as well as the specific products suitable to the customer’s requirements in respect of controlling granulation and hydration to meet the specific use of the product. We produce the controlled Hydration qualities. (Agri) We are specialized to 300 mesh in which we can supply any required viscosity and required filteration as per the customers requirements. We produce the alkaline soluble gums used in the textile Industries as well as in Oil well drilling as viscosifier/Gelling agent grade II and III. We are now concentrating for producing Carboxy-methylated Guar Gum, Hydroxy-Propylated and Ethylated Guar Gum, Oxidised and Cationic Guar Gum as New Developments. Packing and storage: Packing will be done in Master White Kraft Paper Bag HDPE Laminated of 25 Kg Net consisting of Poly Ethylene liners. Shelf Life: 2 years from the date of production provided Stored in a Cool and Dry Place.', '', '', '', '', '', 'images/guar-gum-powder.jpg', '{}', CURRENT_TIMESTAMP, 'SYSTEM_USER', CURRENT_TIMESTAMP, 'SYSTEM_USER');
